-- Hospital sample database (hospital-sample-database) v1 — sqlite
-- Synthetic sample data, CC0-1.0. Deterministic: the same spec and seed produce this byte for byte.
-- seed: flagship:hospital-sample-database:1k
-- Engine 2 (faker 10.6.0), locale en_US. UTF-8.
-- Tables in dependency order; foreign keys are added after the data.

BEGIN;

CREATE TABLE "allergies" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "description" TEXT NOT NULL,
    "name" TEXT NOT NULL UNIQUE
);

CREATE TABLE "departments" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "description" TEXT NOT NULL,
    "name" TEXT NOT NULL UNIQUE,
    "phone" TEXT NOT NULL
);

CREATE TABLE "insurance_providers" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "address" TEXT NOT NULL,
    "contact_person" TEXT NOT NULL,
    "email" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "phone" TEXT NOT NULL
);

CREATE TABLE "inventory_categories" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "description" TEXT NOT NULL,
    "name" TEXT NOT NULL UNIQUE
);

CREATE TABLE "inventory_items" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "category_id" INTEGER NOT NULL,
    "description" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "quantity_in_stock" INTEGER NOT NULL,
    "unit_price" NUMERIC(14,2) NOT NULL,
    FOREIGN KEY ("category_id") REFERENCES "inventory_categories" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "lab_tests" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "cost" NUMERIC(14,2) NOT NULL,
    "description" TEXT NOT NULL,
    "name" TEXT NOT NULL UNIQUE
);

CREATE TABLE "medications" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "brand" TEXT NOT NULL,
    "description" TEXT NOT NULL,
    "dosage_form" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "strength" TEXT NOT NULL
);

CREATE TABLE "patients" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "address" TEXT NOT NULL,
    "date_of_birth" TEXT NOT NULL,
    "email" TEXT NOT NULL,
    "emergency_contact" TEXT NOT NULL,
    "first_name" TEXT NOT NULL,
    "gender" TEXT NOT NULL,
    "last_name" TEXT NOT NULL,
    "phone" TEXT NOT NULL
);

CREATE TABLE "billing" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "billing_date" TEXT NOT NULL,
    "paid_amount" NUMERIC(14,2) NOT NULL,
    "patient_id" INTEGER NOT NULL,
    "status" TEXT NOT NULL,
    "total_amount" NUMERIC(14,2) NOT NULL,
    FOREIGN KEY ("patient_id") REFERENCES "patients" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "billing_items" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "amount" NUMERIC(14,2) NOT NULL,
    "billing_id" INTEGER NOT NULL,
    "description" TEXT NOT NULL,
    FOREIGN KEY ("billing_id") REFERENCES "billing" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "insurance_policies" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "coverage_details" TEXT NOT NULL,
    "expiry_date" TEXT NOT NULL,
    "patient_id" INTEGER NOT NULL UNIQUE,
    "policy_number" TEXT NOT NULL UNIQUE,
    "provider_id" INTEGER NOT NULL,
    FOREIGN KEY ("patient_id") REFERENCES "patients" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("provider_id") REFERENCES "insurance_providers" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "patient_allergies" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "allergy_id" INTEGER NOT NULL,
    "patient_id" INTEGER NOT NULL,
    "severity" TEXT NOT NULL,
    FOREIGN KEY ("allergy_id") REFERENCES "allergies" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("patient_id") REFERENCES "patients" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "payments" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "amount" NUMERIC(14,2) NOT NULL,
    "billing_id" INTEGER NOT NULL UNIQUE,
    "payment_date" TEXT NOT NULL,
    "payment_method" TEXT NOT NULL,
    FOREIGN KEY ("billing_id") REFERENCES "billing" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "staff_roles" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "description" TEXT NOT NULL,
    "title" TEXT NOT NULL UNIQUE
);

CREATE TABLE "staff" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "department_id" INTEGER NOT NULL,
    "email" TEXT NOT NULL UNIQUE,
    "first_name" TEXT NOT NULL,
    "hire_date" TEXT NOT NULL,
    "last_name" TEXT NOT NULL,
    "phone" TEXT NOT NULL,
    "role_id" INTEGER NOT NULL,
    FOREIGN KEY ("department_id") REFERENCES "departments" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("role_id") REFERENCES "staff_roles" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "doctors" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "biography" TEXT NOT NULL,
    "license_number" TEXT NOT NULL UNIQUE,
    "specialty" TEXT NOT NULL,
    "staff_id" INTEGER NOT NULL UNIQUE,
    FOREIGN KEY ("staff_id") REFERENCES "staff" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "appointments" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "appointment_date" TEXT NOT NULL,
    "doctor_id" INTEGER NOT NULL,
    "notes" TEXT,
    "patient_id" INTEGER NOT NULL,
    "status" TEXT NOT NULL,
    FOREIGN KEY ("doctor_id") REFERENCES "doctors" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("patient_id") REFERENCES "patients" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "medical_records" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "created_at" TEXT NOT NULL,
    "diagnosis" TEXT NOT NULL,
    "doctor_id" INTEGER NOT NULL,
    "patient_id" INTEGER NOT NULL,
    "treatment_plan" TEXT NOT NULL,
    FOREIGN KEY ("doctor_id") REFERENCES "doctors" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("patient_id") REFERENCES "patients" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "lab_requests" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "doctor_id" INTEGER NOT NULL,
    "medical_record_id" INTEGER NOT NULL,
    "request_date" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "test_id" INTEGER NOT NULL,
    FOREIGN KEY ("doctor_id") REFERENCES "doctors" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("medical_record_id") REFERENCES "medical_records" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("test_id") REFERENCES "lab_tests" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "lab_results" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "performed_date" TEXT NOT NULL,
    "request_id" INTEGER NOT NULL UNIQUE,
    "result_details" TEXT NOT NULL,
    "technician_id" INTEGER NOT NULL,
    FOREIGN KEY ("request_id") REFERENCES "lab_requests" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("technician_id") REFERENCES "staff" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "prescriptions" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "doctor_id" INTEGER NOT NULL,
    "instructions" TEXT NOT NULL,
    "medical_record_id" INTEGER NOT NULL,
    "prescribed_date" TEXT NOT NULL,
    FOREIGN KEY ("doctor_id") REFERENCES "doctors" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("medical_record_id") REFERENCES "medical_records" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "prescription_items" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "dosage" TEXT NOT NULL,
    "duration" TEXT NOT NULL,
    "frequency" TEXT NOT NULL,
    "medication_id" INTEGER NOT NULL,
    "prescription_id" INTEGER NOT NULL,
    FOREIGN KEY ("medication_id") REFERENCES "medications" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("prescription_id") REFERENCES "prescriptions" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "schedules" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "day_of_week" TEXT,
    "shift_end" TEXT NOT NULL,
    "shift_start" TEXT NOT NULL,
    "staff_id" INTEGER NOT NULL,
    FOREIGN KEY ("staff_id") REFERENCES "staff" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "surgeries" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "description" TEXT NOT NULL,
    "name" TEXT NOT NULL UNIQUE,
    "risk_level" TEXT NOT NULL
);

CREATE TABLE "vendors" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "address" TEXT NOT NULL,
    "contact_name" TEXT NOT NULL,
    "email" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "phone" TEXT NOT NULL
);

CREATE TABLE "purchase_orders" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "order_date" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "total_cost" NUMERIC(14,2) NOT NULL,
    "vendor_id" INTEGER NOT NULL,
    FOREIGN KEY ("vendor_id") REFERENCES "vendors" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "purchase_order_items" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "item_id" INTEGER NOT NULL,
    "purchase_order_id" INTEGER NOT NULL,
    "quantity" INTEGER NOT NULL,
    "unit_price" NUMERIC(14,2) NOT NULL,
    FOREIGN KEY ("item_id") REFERENCES "inventory_items" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("purchase_order_id") REFERENCES "purchase_orders" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "visitors" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "name" TEXT NOT NULL,
    "patient_id" INTEGER NOT NULL,
    "relationship" TEXT NOT NULL,
    "visit_time_in" TEXT NOT NULL,
    "visit_time_out" TEXT NOT NULL,
    FOREIGN KEY ("patient_id") REFERENCES "patients" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "wards" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "capacity" INTEGER NOT NULL,
    "department_id" INTEGER NOT NULL,
    "name" TEXT NOT NULL UNIQUE,
    "type" TEXT NOT NULL,
    FOREIGN KEY ("department_id") REFERENCES "departments" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "rooms" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "room_number" TEXT NOT NULL UNIQUE,
    "status" TEXT NOT NULL,
    "type" TEXT NOT NULL,
    "ward_id" INTEGER NOT NULL,
    FOREIGN KEY ("ward_id") REFERENCES "wards" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "beds" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "bed_number" TEXT NOT NULL UNIQUE,
    "room_id" INTEGER NOT NULL,
    "status" TEXT NOT NULL,
    FOREIGN KEY ("room_id") REFERENCES "rooms" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "admissions" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "admission_date" TEXT NOT NULL,
    "bed_id" INTEGER NOT NULL,
    "discharge_date" TEXT NOT NULL,
    "patient_id" INTEGER NOT NULL,
    "primary_diagnosis" TEXT NOT NULL,
    FOREIGN KEY ("bed_id") REFERENCES "beds" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("patient_id") REFERENCES "patients" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "surgical_procedures" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "admission_id" INTEGER NOT NULL UNIQUE,
    "duration_minutes" INTEGER NOT NULL,
    "lead_surgeon_id" INTEGER NOT NULL,
    "scheduled_time" TEXT NOT NULL,
    "surgery_id" INTEGER NOT NULL,
    FOREIGN KEY ("admission_id") REFERENCES "admissions" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("lead_surgeon_id") REFERENCES "doctors" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("surgery_id") REFERENCES "surgeries" ("id") DEFERRABLE INITIALLY DEFERRED
);

